      // order [1,2,3], NOT reverse [3,2,1], NOT amount order (100,200,300 -> [2,3,1]) and NOT issued
      // order (Feb,Jul,Nov -> [3,2,1]). Only a genuine due-date sort yields [2,1,3].
      invoices: [
